#:property PublishAot=false

// Find the earliest Friday the 13th in the proleptic Gregorian calendar (starting 0001-01-01)
// and count all Friday the 13ths in a full 400-year cycle.

// Find the earliest Friday the 13th
var date = new DateTime(1, 1, 13); // start checking the 13th of each month
DateTime? earliest = null;

while (date.Year == 1)
{
    if (date.DayOfWeek == DayOfWeek.Friday)
    {
        earliest = date;
        break;
    }
    date = date.AddMonths(1);
}

// If not found in year 1, keep searching
if (earliest is null)
{
    date = new DateTime(2, 1, 13);
    while (earliest is null)
    {
        if (date.DayOfWeek == DayOfWeek.Friday)
            earliest = date;
        else
            date = date.AddMonths(1);
    }
}

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd} ({earliest:dddd})");

// Count Friday the 13ths in a full 400-year cycle (the Gregorian calendar repeats every 400 years)
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateTime(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");

// Bonus: distribution by month
var byMonth = new int[12];
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateTime(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
            byMonth[month - 1]++;
    }
}

Console.WriteLine("\nDistribution by month (over 400 years):");
for (int m = 0; m < 12; m++)
{
    Console.WriteLine($"  {new DateTime(2000, m + 1, 1):MMMM,-12} {byMonth[m]}");
}

